<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/app/bootstrap.php';
$user=require_app_user();
render_app_start('Profile','profile','Account identity','Review the active account, role assignments, company memberships, and recent activity.','');
?>
<div class="profile-layout"><section class="profile-card"><div class="profile-avatar"><?= h(initials($user['name'])) ?></div><span class="eyebrow"><?= demo_mode_active()?'Demo account':'Production account' ?></span><h2><?= h($user['name']) ?></h2><p><?= h($user['job_title']??'') ?> · <?= h($user['department']??'') ?></p><dl><div><dt>Email</dt><dd><?= h($user['email']) ?></dd></div><div><dt>Phone</dt><dd><?= h($user['phone']??'—') ?></dd></div><div><dt>Status</dt><dd><?= badge($user['status']) ?></dd></div><div><dt>Last login</dt><dd><?= h(date_us($user['last_login']??null,true)) ?></dd></div></dl><?php if(!demo_mode_active()): ?><div class="control-list"><a class="button secondary full" href="<?= h(app_url('change-password.php')) ?>">Change password</a></div><?php endif; ?></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Authorization</span><h2>Roles and company memberships</h2></div></header><div class="profile-section"><h3>Assigned roles</h3><div class="tag-list"><?php foreach(current_role_codes($user) as $role): ?><span><?= h(data_role_name($role)) ?></span><?php endforeach; ?></div></div><div class="profile-section"><h3>Company memberships</h3><div class="membership-list"><?php foreach($user['company_ids']??[] as $companyId): ?><article><strong><?= h(data_company_name($companyId)) ?></strong><small><?= (int)$companyId===(int)$user['primary_company_id']?'Primary company':'Assigned company' ?></small></article><?php endforeach; ?></div></div><div class="profile-section"><h3>Effective permissions</h3><div class="permission-token-list"><?php foreach(array_slice(current_permissions($user),0,36) as $permission): ?><code><?= h($permission) ?></code><?php endforeach; ?></div></div></section></div>
<?php render_app_end(); ?>
